local function utf8_char(cp)
    if not cp or cp == 0 then return nil end
    if cp < 0x80 then
        return string.char(cp)
    elseif cp < 0x800 then
        return string.char(0xC0 + math.floor(cp / 64), 0x80 + (cp % 64))
    elseif cp < 0x10000 then
        return string.char(
            0xE0 + math.floor(cp / 4096),
            0x80 + (math.floor(cp / 64) % 64),
            0x80 + (cp % 64)
        )
    else
        return string.char(
            0xF0 + math.floor(cp / 262144),
            0x80 + (math.floor(cp / 4096) % 64),
            0x80 + (math.floor(cp / 64) % 64),
            0x80 + (cp % 64)
        )
    end
end

local function plane_cp(ku, ten)
    if ku < 1 or ku > 94 or ten < 1 or ten > 94 then return 0 end
    local i = ((ku - 1) * 94 + (ten - 1)) * 2 + 1
    local a, b = PLANE:byte(i, i + 1)
    if not a or not b then return 0 end
    return a * 256 + b
end

function M.to_utf8(s)
    if type(s) ~= 'string' or s == '' then return s or '' end
    local out, i, n = {}, 1, #s
    while i <= n do
        local c = s:byte(i)
        if c < 0x80 then
            out[#out + 1] = string.char(c)
            i = i + 1
        elseif c >= 0xA1 and c <= 0xDF then
            out[#out + 1] = utf8_char(0xFF61 + (c - 0xA1))
            i = i + 1
        elseif (c >= 0x81 and c <= 0x9F) or (c >= 0xE0 and c <= 0xFC) then
            local d = (i < n) and s:byte(i + 1) or nil
            if not d then
                i = i + 1
            else
                local word = c * 256 + d
                local cp = EX[word]
                if not cp then
                    local p, q = c, d
                    if p >= 0xE0 then p = p - 0x40 end
                    if q >= 0x80 then q = q - 1 end
                    local ku = (p - 0x81) * 2 + ((q >= 0x9E) and 1 or 0) + 1
                    local ten = (q >= 0x9E) and (q - 0x9E + 1) or (q - 0x40 + 1)
                    cp = plane_cp(ku, ten)
                end
                if cp and cp > 0 then
                    out[#out + 1] = utf8_char(cp)
                end
                i = i + 2
            end
        else
            i = i + 1
        end
    end
    return table.concat(out)
end

return M
